tape( 'the function returns a reference to the input vector', function test( t ) {
	var data;
	var out;
	var x;

	data = rutu;

	x = new Complex64Array( data.x );

	out = ctrsv( data.uplo, data.trans, data.diag, data.N, new Complex64Array( data.A ), data.strideA1, data.strideA2, data.offsetA, x, data.strideX, data.offsetX );
	t.strictEqual( out, x, 'returns expected value' );

	t.end();
});

tape( 'if `N` is zero, the function returns the input vector unchanged', function test( t ) {
	var data;
	var out;
	var x;

	data = rutu;

	x = new Complex64Array( data.x );

	out = ctrsv( data.uplo, data.trans, data.diag, 0, new Complex64Array( data.A ), data.strideA1, data.strideA2, data.offsetA, x, data.strideX, data.offsetX );
	t.strictEqual( out, x, 'returns expected value' );
	isEqualC64( t, x, data.x, 'returns expected value' );

	t.end();
});
